log=''
class Bad:
 def __iter__(self):
  global log
  log=log+'i'
  return 1
try:
 list(Bad())
except TypeError:
 result=log+'t'

class Bad:
 __next__=1
try:
 result=next(Bad(),9)
except TypeError:
 result='type'

log=''
class Pair:
 def __init__(self):
  self.i=0
 def __iter__(self):
  return self
 def __next__(self):
  global log
  self.i=self.i+1
  log=log+str(self.i)
  if self.i<=3:
   return self.i
  raise StopIteration
try:
 dict([Pair()])
except ValueError:
 result=log+'v'

log=''
class Keys:
 def __init__(self):
  self.i=0
 def __iter__(self):
  global log
  log=log+'i'
  return self
 def __length_hint__(self):
  global log
  log=log+'h'
  return 2
 def __next__(self):
  global log
  log=log+'n'
  self.i=self.i+1
  if self.i==1:
   return 'a'
  if self.i==2:
   return 'b'
  raise StopIteration
class Mapping:
 def keys(self):
  global log
  log=log+'k'
  return Keys()
 def __getitem__(self,key):
  global log
  log=log+key
  return key
result=dict(Mapping())
result=log
